INSERT INTO cortes (slug, comprimento, manutencao_semanas, nome, descricao, como_pedir) VALUES
('degrade-navalhado', 'curto', 2,
 '{"pt": "Degradê navalhado", "en": "Skin fade", "es": "Degradado a navaja"}',
 '{"pt": "Laterais e nuca que somem até a pele, com transição suave para o topo.", "en": "Sides and back fade down to the skin with a smooth blend into the top.", "es": "Laterales y nuca que bajan hasta la piel con transición suave hacia arriba."}',
 '{"pt": "Peça degradê começando no zero com navalha, subindo até a pente 2 ou 3 nas têmporas, e diga quanto quer tirar do topo.", "en": "Ask for a skin fade starting with a razor, blending up to a 2 or 3 guard at the temples, and say how much to take off the top.", "es": "Pide un degradado desde la piel con navaja, subiendo hasta el peine 2 o 3 en las sienes, y di cuánto quitar arriba."}'),
('degrade-baixo', 'curto', 3,
 '{"pt": "Degradê baixo", "en": "Low fade", "es": "Degradado bajo"}',
 '{"pt": "O degradê começa logo acima da orelha, mantendo mais volume nas laterais.", "en": "The fade starts just above the ear, keeping more weight on the sides.", "es": "El degradado empieza justo encima de la oreja y mantiene más volumen en los lados."}',
 '{"pt": "Peça degradê baixo, começando na altura da orelha, com pente 1 embaixo e 3 em cima.", "en": "Ask for a low fade starting at ear level, a 1 guard at the bottom blending into a 3.", "es": "Pide un degradado bajo desde la altura de la oreja, peine 1 abajo y 3 arriba."}'),
('taper', 'curto', 3,
 '{"pt": "Taper (pezinho degradê)", "en": "Taper fade", "es": "Taper"}',
 '{"pt": "Degradê só nas costeletas e na nuca. Discreto e fácil de manter.", "en": "Fade only at the sideburns and neckline. Subtle and easy to keep.", "es": "Degradado solo en patillas y nuca. Discreto y fácil de mantener."}',
 '{"pt": "Peça taper nas costeletas e na nuca, mantendo as laterais com tesoura ou pente 3.", "en": "Ask for a taper at the sideburns and neckline, keeping the sides with scissors or a 3 guard.", "es": "Pide un taper en patillas y nuca, dejando los lados a tijera o peine 3."}'),
('maquina', 'curto', 2,
 '{"pt": "Corte na máquina (buzz cut)", "en": "Buzz cut", "es": "Rapado a máquina"}',
 '{"pt": "Mesmo comprimento curto na cabeça toda. Prático e marcante.", "en": "One short length all over. Practical and striking.", "es": "Un mismo largo corto en toda la cabeza. Práctico y llamativo."}',
 '{"pt": "Peça máquina no mesmo pente em toda a cabeça (por exemplo, pente 2) e acabamento no pezinho.", "en": "Ask for the same guard all over (for example a 2) and a clean neckline.", "es": "Pide el mismo peine en toda la cabeza (por ejemplo, el 2) y nuca limpia."}'),
('militar', 'curto', 3,
 '{"pt": "Corte militar (crew cut)", "en": "Crew cut", "es": "Corte militar"}',
 '{"pt": "Laterais curtas e topo um pouco maior, levemente mais longo na frente.", "en": "Short sides with a slightly longer top, a touch longer at the front.", "es": "Lados cortos y parte superior un poco más larga, algo más al frente."}',
 '{"pt": "Peça laterais no pente 2 e topo com 2 a 3 cm, deixando a frente um pouco maior.", "en": "Ask for a 2 guard on the sides and 2 to 3 cm on top, slightly longer at the front.", "es": "Pide peine 2 en los lados y 2 a 3 cm arriba, algo más largo al frente."}'),
('topete', 'curto', 4,
 '{"pt": "Topete (pompadour)", "en": "Pompadour", "es": "Tupé"}',
 '{"pt": "Volume alto penteado para trás, com laterais curtas.", "en": "High volume swept back with short sides.", "es": "Volumen alto peinado hacia atrás con lados cortos."}',
 '{"pt": "Peça topete com 6 a 8 cm na frente, diminuindo para trás, e laterais em degradê.", "en": "Ask for 6 to 8 cm at the front tapering back, with faded sides.", "es": "Pide 6 a 8 cm al frente, disminuyendo hacia atrás, con lados degradados."}'),
('quiff', 'curto', 4,
 '{"pt": "Quiff (topete texturizado)", "en": "Quiff", "es": "Quiff"}',
 '{"pt": "Frente para cima com textura e movimento, mais solto que o topete clássico.", "en": "Front swept up with texture and movement, looser than a pompadour.", "es": "Frente hacia arriba con textura y movimiento, más suelto que el tupé."}',
 '{"pt": "Peça a franja para cima com 5 a 7 cm, topo texturizado com tesoura e laterais curtas.", "en": "Ask for 5 to 7 cm at the front styled up, a textured top and short sides.", "es": "Pide 5 a 7 cm al frente hacia arriba, parte superior texturizada y lados cortos."}'),
('crop-frances', 'curto', 3,
