 '{"pt": "Peça camadas curtas na altura do queixo ao redor do rosto e camadas longas no restante, mantendo o comprimento.", "en": "Ask for chin-length face-framing layers and long layers elsewhere, keeping the length.", "es": "Pide capas cortas a la altura del mentón alrededor del rostro y capas largas en el resto, manteniendo el largo."}'),
('corte-v', 'longo', 10,
 '{"pt": "Corte em V", "en": "V-cut", "es": "Corte en V"}',
 '{"pt": "Pontas que formam um V nas costas, deixando o centro mais longo.", "en": "Ends that form a V at the back, longest in the centre.", "es": "Puntas que forman una V en la espalda, más largas en el centro."}',
 '{"pt": "Peça as pontas em V nas costas, com camadas leves para dar movimento.", "en": "Ask for V-shaped ends at the back with light layers for movement.", "es": "Pide las puntas en V en la espalda, con capas ligeras para dar movimiento."}'),
('black-power', 'medio', 6,
 '{"pt": "Black power modelado", "en": "Shaped afro", "es": "Afro esculpido"}',
