 '{"pt": "Peça para modelar o black power em formato arredondado com o cabelo seco e esticado no pente garfo, aparando só o necessário.", "en": "Ask to shape the afro round on dry hair picked out with an afro comb, trimming only what is needed.", "es": "Pide esculpir el afro en forma redondeada con el cabello seco y abierto con peine de púas, recortando solo lo necesario."}');

-- Todos os modelos reconhecem o catálogo completo.
INSERT INTO espelho_cortes (espelho_id, corte_id)
SELECT e.id, c.id FROM espelhos e CROSS JOIN cortes c;

-- Exemplos mostrados em cada modelo na página /espelho.
UPDATE espelho_cortes ec SET destaque = TRUE
FROM espelhos e, cortes c
WHERE ec.espelho_id = e.id AND ec.corte_id = c.id AND (
    (e.slug = 'retangular'    AND c.slug IN ('degrade-navalhado', 'topete', 'crop-frances', 'cacheado-degrade')) OR
    (e.slug = 'oval'          AND c.slug IN ('chanel', 'camadas', 'franja-cortina', 'borboleta')) OR
    (e.slug = 'arco'          AND c.slug IN ('wolf-cut', 'mullet', 'long-bob', 'quiff')) OR
    (e.slug = 'redondo'       AND c.slug IN ('pixie', 'taper', 'maquina', 'black-power')) OR
    (e.slug = 'personalizado' AND c.slug IN ('undercut', 'shaggy', 'corte-v', 'social'))
);
